define("local_courseagent/mermaid_loader",["jquery"],function($){var sanitize=function(r){return r.replace(/^```mermaid\s*/i,'').replace(/^```\s*/m,'').replace(/```\s*$/m,'').trim();};var esc=function(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');};var renderOne=async function(el){if(el.getAttribute('data-processed')==='true')return;var code=sanitize(el.textContent||el.innerText||'');if(!code)return;try{await mermaid.parse(code);el.textContent=code;await mermaid.run({nodes:[el]});}catch(err){var msg='Syntax error \u2014 check the diagram code below.';if(err&&err.message)msg=err.message.split('\n')[0].trim().substring(0,160);el.innerHTML='<div style="border:1px solid #e07c24;border-radius:6px;padding:14px 16px;background:#fffbf5;font-family:inherit;"><p style="margin:0 0 6px;color:#b45309;font-weight:600;font-size:.9em;">\u26a0 Diagram could not be rendered</p><p style="margin:0 0 10px;color:#78716c;font-size:.82em;">'+esc(msg)+'</p><details style="cursor:pointer;"><summary style="color:#a16207;font-size:.82em;user-select:none;">Show diagram source</summary><pre style="margin:8px 0 0;font-size:.78em;background:#f8f7f4;padding:10px;border-radius:4px;overflow-x:auto;white-space:pre-wrap;color:#44403c;">'+esc(code)+'</pre></details></div>';el.removeAttribute('data-processed');}};return{init:function(url){$(document).ready(function(){if($('.mermaid').length===0)return;var run=function(){mermaid.initialize({startOnLoad:false,theme:'default',securityLevel:'loose'});document.querySelectorAll('.mermaid').forEach(function(el){renderOne(el);});};if(typeof mermaid==='undefined'){var s=document.createElement('script');s.src=url;s.onload=run;s.onerror=function(){console.warn('[CourseAgent] Failed to load mermaid.js from: '+url);};document.head.appendChild(s);}else{run();}});}};});
